# Identify connected same-color components, 8 considered components
R=C=10; seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v and (r,c) not in seen:
   stack=[(r,c)];seen.add((r,c)); comp=[]
   while stack:
    p=stack.pop();comp.append(p)
    for q in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)):
     if 0<=q[0]<R and 0<=q[1]<C and q not in seen and grid[q[0]][q[1]]==v: seen.add(q);stack.append(q)
   comps.append((v,comp))
# step all components right if their target cells are empty or occupied by same component; synchronous
while True:
 occ={p:i for i,(_,co) in enumerate(comps) for p in co}; can=[]
 for i,(v,co) in enumerate(comps):
  ok=True
  for r,c in co:
   if c+1>=C or ((r,c+1) in occ and occ[(r,c+1)]!=i):ok=False;break
  can.append(ok)
 if not any(can):break
 comps=[(v,[(r,c+1) for r,c in co] if can[i] else co) for i,(v,co) in enumerate(comps)]
out=[[0]*C for _ in range(R)]
for v,co in comps:
 for r,c in co:out[r][c]=v
out
